    private void analyzeCameraSpeech(){if(project==null||project.clips.isEmpty()){notifyUser("Add a main video clip first");return;}EditorProject target=project;ArrayList<EditorProject.Clip> sources=new ArrayList<>(project.clips);java.util.concurrent.atomic.AtomicBoolean canceled=new java.util.concurrent.atomic.AtomicBoolean();ProgressDialog dialog=new ProgressDialog(this);dialog.setTitle("Analyze camera speech");dialog.setMessage("Finding audio activity on this phone. Music will lower during detected sound; loud background sound can also trigger it.");dialog.setIndeterminate(true);dialog.setCancelable(true);dialog.setOnCancelListener(d->canceled.set(true));dialog.show();pausePlayback();io.execute(()->{ArrayList<float[]> activity=new ArrayList<>();String failure="";try{for(EditorProject.Clip c:sources){if(canceled.get()||!active)throw new java.io.InterruptedIOException("Analysis canceled");try{activity.add(EditorWaveform.decode(c.uri,c.duration,()->active&&!canceled.get()&&getSystemService(android.os.PowerManager.class).getCurrentThermalStatus()<3));}catch(IllegalArgumentException noAudio){activity.add(new float[0]);}}}catch(Exception e){failure=e.getMessage();}String error=failure;main.post(()->{dialog.dismiss();if(project!=target||isFinishing()||canceled.get())return;if(!error.isEmpty()){notifyUser(error);return;}checkpoint();int ready=0;for(int i=0;i<sources.size();i++)if(project.clips.contains(sources.get(i))){sources.get(i).speechActivity=activity.get(i);sources.get(i).speechSource=activity.get(i).length>0;if(sources.get(i).speechSource)ready++;}project.duckCameraSpeech=ready>0;committed();notifyUser(ready>0?"Camera speech activity ready · enable Duck on your music tracks":"No camera audio found");});});}
