    private void duckingSettings(){if(project==null)return;LinearLayout panel=column();panel.addView(button("Duck all music / non-narration audio",()->{checkpoint();for(EditorProject.Audio sound:project.audios)if(!sound.narration)sound.duck=true;committed();notifyUser("Ducking enabled on non-narration audio tracks");}));panel.addView(button(project.duckCameraSpeech?"Re-analyze camera speech":"Analyze main camera speech",this::analyzeCameraSpeech));Switch cameraSpeech=new Switch(this);cameraSpeech.setText("Use camera speech for music ducking");cameraSpeech.setTextColor(TEXT);cameraSpeech.setChecked(project.duckCameraSpeech);cameraSpeech.setOnCheckedChangeListener((v,on)->{checkpoint();project.duckCameraSpeech=on;committed();});panel.addView(cameraSpeech);panel.addView(text("Mark voice tracks as Narration, then enable Duck on your music track. Speech activity lowers only the tracks you choose, in playback and export.",13,TEXT));for(EditorProject.Audio a:project.audios){Switch voice=new Switch(this);voice.setText("Narration · "+a.name);voice.setTextColor(TEXT);voice.setChecked(a.narration);voice.setOnCheckedChangeListener((v,on)->{checkpoint();a.narration=on;if(on)a.duck=false;save();if(on)analyzeNarration(a);else if(livePreview!=null)livePreview.bind(project);});panel.addView(voice);Switch duck=new Switch(this);duck.setText("Duck · "+a.name);duck.setTextColor(TEXT);duck.setChecked(a.duck);duck.setOnCheckedChangeListener((v,on)->{checkpoint();a.duck=on;if(on)a.narration=false;committed();});panel.addView(duck);}TextView strength=text("Reduction · "+Math.round(project.duckStrength*100)+"%",12,ACCENT);panel.addView(strength);SeekBar amount=new SeekBar(this);amount.setMax(100);amount.setProgress((int)(project.duckStrength*100));amount.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){checkpoint();}public void onStopTrackingTouch(SeekBar b){committed();}public void onProgressChanged(SeekBar b,int p,boolean user){if(user){project.duckStrength=p/100.;strength.setText("Reduction · "+p+"%");if(livePreview!=null)livePreview.bind(project);}}});panel.addView(amount);TextView fade=text("Fade · "+project.duckFadeMs+" ms",12,ACCENT);panel.addView(fade);SeekBar smoothing=new SeekBar(this);smoothing.setMax(1980);smoothing.setProgress((int)project.duckFadeMs-20);smoothing.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){checkpoint();}public void onStopTrackingTouch(SeekBar b){committed();}public void onProgressChanged(SeekBar b,int p,boolean user){if(user){project.duckFadeMs=p+20;fade.setText("Fade · "+project.duckFadeMs+" ms");if(livePreview!=null)livePreview.bind(project);}}});panel.addView(smoothing);if(project.audios.isEmpty())panel.addView(button("Add audio",this::showAudioImportScreen));ScrollView scroll=new ScrollView(this);scroll.addView(panel);new AlertDialog.Builder(this).setTitle("Music ducking").setView(scroll).setPositiveButton("Done",null).show();}
    private void cancelVoiceover(){voiceCountdownToken++;if(voiceRecorder!=null){voiceRecorder.close();voiceRecorder=null;}if(livePreview!=null){livePreview.muteMonitoring(false);livePreview.pause();}if(voiceDialog!=null){voiceDialog.dismiss();voiceDialog=null;}}
    private void recordVoiceover(){
        if(project==null||project.referenceClip()==null){notifyUser("Add a video, photo or text before recording narration");return;}if(exporting||voiceRecorder!=null)return;
        if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED){voicePermissionPending=true;requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},71);return;}
        pausePlayback();long at=currentPosition();if(at>=project.duration()){at=0;if(livePreview!=null)livePreview.seekTo(0);}final long startAt=at;EditorProject target=project;final File[] take={null};final boolean[] recording={false};LinearLayout panel=column();TextView status=text("Narration starts at "+time(startAt)+". Playback sound is muted to prevent feedback.",14,TEXT);panel.addView(status);Button recordTake=button("● Record / retry",()->{}),stopTake=button("■ Stop",()->{}),use=button("✓ Add voice-over",()->{});panel.addView(recordTake);panel.addView(stopTake);panel.addView(use);use.setEnabled(false);stopTake.setEnabled(false);
        voiceDialog=new AlertDialog.Builder(this).setTitle("Record voice-over").setView(panel).setNegativeButton("Cancel",null).create();AlertDialog dialog=voiceDialog;
        Runnable stop=()->{if(!recording[0]||voiceRecorder==null)return;recording[0]=false;try{take[0]=voiceRecorder.finish();voiceRecorder=null;pausePlayback();if(livePreview!=null)livePreview.muteMonitoring(false);use.setEnabled(true);status.setText("Take ready · add it or tap Record / retry");}catch(Exception e){status.setText(e.getMessage());if(voiceRecorder!=null)voiceRecorder.close();voiceRecorder=null;}recordTake.setEnabled(true);stopTake.setEnabled(false);};
        stopTake.setOnClickListener(v->stop.run());recordTake.setOnClickListener(v->{if(take[0]!=null){take[0].delete();take[0]=null;}use.setEnabled(false);recordTake.setEnabled(false);int token=++voiceCountdownToken;main.post(new Runnable(){int remaining=3;public void run(){if(token!=voiceCountdownToken||!dialog.isShowing()||!active)return;if(remaining>0){status.setText("Ready… "+remaining--);main.postDelayed(this,1000);return;}try{voiceRecorder=new CreatorRecorder();voiceRecorder.start(EditorActivity.this,0);recording[0]=true;stopTake.setEnabled(true);if(livePreview!=null){livePreview.seekTo(startAt);livePreview.muteMonitoring(true);livePreview.play();}main.post(new Runnable(){public void run(){if(token!=voiceCountdownToken||voiceRecorder==null||!recording[0])return;status.setText("Recording · "+time(voiceRecorder.elapsed()));if(voiceRecorder.elapsed()>=Math.min(600000,Math.max(300,project.duration()-startAt)))stop.run();else main.postDelayed(this,150);}});}catch(Exception e){if(voiceRecorder!=null)voiceRecorder.close();voiceRecorder=null;recordTake.setEnabled(true);status.setText("Cannot record: "+e.getMessage());}}});});
        use.setOnClickListener(v->{if(take[0]==null||project!=target)return;File captured=take[0];take[0]=null;dialog.dismiss();notifyUser("Adding voice-over…");io.execute(()->{try{EditorProject.Audio sound=EditorAudio.importFile(this,Uri.fromFile(captured),"Voice-over");sound.narration=true;if(active&&getSystemService(android.os.PowerManager.class).getCurrentThermalStatus()<3)try{sound.activity=EditorWaveform.decode(sound.uri,sound.duration,()->active&&getSystemService(android.os.PowerManager.class).getCurrentThermalStatus()<3);}catch(java.io.InterruptedIOException paused){sound.activity=new float[0];}main.post(()->{if(!active||project!=target||isFinishing()){new File(sound.uri).delete();return;}checkpoint();sound.at=startAt;sound.track=project.audioTracks();project.audios.add(sound);selectedAudio=project.audios.size()-1;selectedTrack="Audio";selectedCaption=selectedOverlay=-1;tool="Music";position=startAt;save();showEditor();});}catch(Exception e){main.post(()->notifyUser("Voice-over failed: "+e.getMessage()));}finally{captured.delete();}});});
        dialog.setOnDismissListener(d->{voiceCountdownToken++;if(voiceRecorder!=null){voiceRecorder.close();voiceRecorder=null;}if(livePreview!=null){livePreview.muteMonitoring(false);livePreview.pause();}if(take[0]!=null)take[0].delete();if(voiceDialog==dialog)voiceDialog=null;});dialog.show();
    }
