    private void takeMarkers(){if(project==null||selected<0||selected>=project.clips.size()){notifyUser("Select a main video clip to view its take markers");return;}EditorProject.Clip clip=project.clips.get(selected);LinearLayout panel=column();for(String kind:new String[]{"good","mistake"})panel.addView(button(kind.equals("good")?"★ Mark good moment":"! Mark mistake",()->{checkpoint();try{long source=clip.start+(long)((currentPosition()-project.offset(selected))*clip.speed);clip.markers.put(new org.json.JSONObject().put("at",Math.max(clip.start,Math.min(clip.end-1,source))).put("kind",kind));committed();notifyUser("Marker added");}catch(Exception e){notifyUser(e.getMessage());}}));for(int i=0;i<clip.markers.length();i++){org.json.JSONObject marker=clip.markers.optJSONObject(i);if(marker==null)continue;long source=marker.optLong("at");if(source<clip.start||source>=clip.end)continue;long at=project.offset(selected)+(long)((source-clip.start)/clip.speed);Button item=button((marker.optString("kind").equals("good")?"★ Good":"! Retake")+" · "+time(at),()->{position=at;if(livePreview!=null)livePreview.seekTo(at);refreshTimeline();});final int index=i;item.setOnLongClickListener(v->{checkpoint();for(int n=0;n<clip.markers.length();n++)if(clip.markers.optJSONObject(n)==marker){clip.markers.remove(n);break;}committed();panel.removeView(item);return true;});panel.addView(item);}panel.addView(text("Markers follow source footage through trims and speed changes. Hold a marker to remove it.",12,MUTED));ScrollView scroll=new ScrollView(this);scroll.addView(panel);new AlertDialog.Builder(this).setTitle("Take markers").setView(scroll).setPositiveButton("Done",null).show();}
