    private void startSourcePlayer(){releasePlayer();try{ExoPlayer p=new ExoPlayer.Builder(this).build();player=p;video.setPlayer(p);p.setMediaItem(MediaItem.fromUri(playbackUri));p.addListener(playerListener);p.prepare();p.seekTo(position);main.removeCallbacks(tick);main.post(tick);}catch(Exception e){notifyUser("Playback failed: "+e.getMessage());}}
