    private long currentPosition(){return editing&&livePreview!=null?livePreview.position():player!=null?player.getCurrentPosition():position;}
    private void pausePlayback(){if(editing&&livePreview!=null)livePreview.pause();else if(player!=null)player.pause();}
    private void togglePlayback(){if(editing){if(livePreview==null)rebuildPreview(false);if(livePreview!=null){if(livePreview.isPlaying())livePreview.pause();else livePreview.play();}}else if(player!=null){if(player.isPlaying())player.pause();else{if(player.getPlaybackState()==Player.STATE_ENDED)player.seekTo(0);player.play();}}}
    private void refreshLive(){if(livePreview!=null){livePreview.refresh();if(placement!=null)placement.invalidate();}}
    private final Runnable tick=new Runnable(){public void run(){if(active&&seek!=null&&(livePreview!=null||player!=null)){long d=editing&&project!=null?project.duration():player.getDuration(),at=currentPosition();position=at;clock.setText(time(at)+" / "+time(Math.max(0,d)));if(!seeking&&d>0)seek.setProgress((int)Math.min(1000,at*1000/d));if(editing&&timeline!=null)timeline.position(at);if(placement!=null)placement.invalidate();if(keyButton!=null){boolean canAnimate=!selectedTrack.equals("Audio")&&!selectedTrack.equals("Effect");keyButton.setEnabled(canAnimate);boolean keyed=canAnimate&&EditorMotion.nearest(clip(),keyTime(),40)!=null;keyButton.setImageDrawable(new CameraIcon("keyframe",keyed?ACCENT:TEXT));if(keyDeleteButton!=null)keyDeleteButton.setVisibility(currentMotionSelection()!=null||keyed?View.VISIBLE:View.GONE);}boolean running=editing?livePreview!=null&&livePreview.isPlaying():player.isPlaying();play.setImageDrawable(new CameraIcon(running?"pause":"play",TEXT));main.postDelayed(this,50);}}};
