        timeline=new EditorTimeline(this,new EditorTimeline.Listener(){public void trackMenu(String kind,int row){multiSelection.track(project,kind,row);selectionActions();}public void beginTrim(){checkpoint();pausePlayback();}public void endTrim(){committed();rebuildTools();}public void transition(int right){transitionDialog(right);}public void addVideo(){if(project.clips.size()>=EditorProject.MAX_CLIPS){notifyUser("Project item limit reached");return;}importingOverlay=false;pick(false);}public void keyframe(long at){selectMotionKey(at);}public void move(String kind,int index,int row,long at){moveTimelineItem(kind,index,row,at);}public void seek(long at){clearMotionSelection();position=at;pausePlayback();if(livePreview!=null)livePreview.seekTo(at);else if(player!=null)player.seekTo(at);if(placement!=null)placement.invalidate();clock.setText(time(at)+" / "+time(project.duration()));}public void select(int index,int layer,int caption,String next){transformKeyOwner=null;clearMotionSelection();if(next.equals("Music"))selectedAudio=index;else if(next.equals("Effect"))selectedEffect=index;else selected=index;selectedCaption=caption;selectedOverlay=layer;selectedTrack=layer>=0?"Overlay":next.equals("Text")?"Text":next.equals("Image")?"Image":next.equals("Sticker")?"Sticker":next.equals("Music")?"Audio":next.equals("Effect")?"Effect":"Video";tool=next.equals("Effect")?"Looks":next.equals("Image")||next.equals("Sticker")?"Transform":next;toolCategory=categoryForTool(next);menuLevel=1;showCategoryTools();refreshTimeline();rebuildTools();}});snapButton.setText(timeline.snapEnabled()?"Snap ON":"Snap OFF");
