    private void selectCategory(String category){if(category.equals("Audio")){showAudioImportScreen();return;}if(category.equals("AI Tools")){showAiToolsScreen();return;}if(category.equals("Smart")){selected=Math.max(0,Math.min(project.clips.size()-1,selected));selectedTrack="Video";selectedOverlay=-1;selectedCaption=-1;toolCategory=category;menuLevel=1;tool="Smart edit";showCategoryTools();rebuildTools();return;}toolCategory=category;menuLevel=1;if(category.equals("Effects")){selectedTrack="Effect";selectedOverlay=-1;selectedCaption=-1;selectedEffect=-1;}String[] tools=toolsForCategory(category);tool=tools.length==0?"Trim":tools[0];showCategoryTools();rebuildTools();}
    private void showCategoryTools(){if(actionItems==null)return;actionItems.removeAllViews();if(menuLevel==0){String[] names={"Edit","Audio","Text","Overlay","Effects","Canvas","AI Tools"};String[] icons={"trim","music","text","overlay","effect","canvas","ai"};for(int i=0;i<names.length;i++){final String category=names[i];addMenuItem(category,icons[i],false,()->selectCategory(category));}return;}addMenuItem("‹ "+toolCategory, "back",false,()->{menuLevel=0;showCategoryTools();rebuildTools();});for(String name:toolsForCategory(toolCategory))addMenuItem(name,toolIcon(name),name.equals(tool),()->selectTool(name));}
