    private String[] toolsForCategory(String category){if(category.equals("Audio"))return new String[]{"Music","Volume","Voice"};if(category.equals("Smart"))return new String[]{"Smart edit"};if(category.equals("Text"))return new String[]{"Title library","My presets","Brand kit","Captions","Tutorial graphics","Profession presets","Save preset","Text","Transform","Animate","Keyframes","Remove"};if(category.equals("Image")&&selectedCaption>=0&&selectedCaption<project.captions.size()&&project.captions.get(selectedCaption).style.privacyBlackout)return new String[]{"Privacy","Keyframes","Duplicate","Remove"};if(category.equals("Image"))return new String[]{"Transform","Crop","Animate","Keyframes","Background remover ◆","Duplicate","Remove"};if(category.equals("Sticker"))return new String[]{"Transform","Animate","Keyframes","Duplicate","Remove"};if(category.equals("Overlay"))return new String[]{"Overlay","Split","Duplicate","Transform","Crop","Mask","Animate","Remove"};if(category.equals("Effects"))return new String[]{"Looks","Adjust","Transition","Stickers","Blackout","Before & after"};if(category.equals("Canvas"))return new String[]{"Canvas","Safe areas","Cover","Image","Background remover ◆","Fullscreen"};return new String[]{"Trim","Split","Blackout","Freeze","Speed","Transform","Crop","Animate","Keyframes","Rotate","Mirror","Duplicate","Remove"};}
    private String toolIcon(String name){switch(name){case "Blackout":case "Privacy":return "mask";case "Captions":case "My presets":case "Save preset":return "text";case "Brand kit":return "settings";case "Tutorial graphics":return "animate";case "Safe areas":return "canvas";case "Cover":return "image";case "Before & after":return "overlay";case "AI Tools":case "Photo background cutout":case "Background remover ◆":return "ai";case "Add":case "Image":case "Overlay":return "add";case "Trim":return "trim";case "Split":return "split";case "Freeze":return "freeze";case "Speed":return "speed";case "Volume":case "Voice":case "Music":return "audio";case "Looks":case "Stickers":return "effect";case "Adjust":return "settings";case "Transition":return "transition";case "Title library":case "Text":return "text";case "Transform":return "transform";case "Crop":return "crop";case "Mask":return "mask";case "Animate":return "animate";case "Keyframes":return "keyframe";case "Canvas":return "canvas";case "Fullscreen":return "fullscreen";case "Rotate":return "rotate";case "Mirror":return "mirror";case "Duplicate":return "duplicate";case "Remove":return "delete";default:return "layout";}}
    private String categoryForTool(String name){if(selectedTrack.equals("Image"))return "Image";if(selectedTrack.equals("Sticker"))return "Sticker";if(Arrays.asList("Music","Volume","Voice").contains(name))return "Audio";if(Arrays.asList("Text").contains(name)||selectedTrack.equals("Text"))return "Text";if(Arrays.asList("Overlay").contains(name)||selectedTrack.equals("Overlay"))return "Overlay";if(Arrays.asList("Looks","Effect","Adjust","Transition","Stickers").contains(name))return "Effects";if(Arrays.asList("Canvas","Image","Fullscreen","Background remover ◆").contains(name))return "Canvas";return "Edit";}
    private boolean objectTrack(){return selectedTrack.equals("Text")||selectedTrack.equals("Image")||selectedTrack.equals("Sticker");}
    private EditorProject.Clip clip(){selected=Math.max(0,Math.min(selected,project.clips.size()-1));if(objectTrack()&&selectedCaption>=0&&selectedCaption<project.captions.size())return project.captions.get(selectedCaption).style;return selectedOverlay>=0&&selectedOverlay<project.overlays.size()?project.overlays.get(selectedOverlay).clip:project.clips.isEmpty()?project.referenceClip():project.clips.get(selected);}
    private long selectedOffset(){if(objectTrack()&&selectedCaption>=0&&selectedCaption<project.captions.size())return project.captions.get(selectedCaption).at;return selectedOverlay>=0&&selectedOverlay<project.overlays.size()?project.overlays.get(selectedOverlay).at:project.offset(selected);}
    private void refreshTimeline(){if(timeline==null||project==null)return;timeline.selection(multiSelection);timeline.bind(project,selectedTrack.equals("Audio")?selectedAudio:selectedTrack.equals("Effect")?selectedEffect:selected,selectedOverlay,selectedCaption,selectedTrack);timeline.position(position);EditorMotion.Key selectedKey=currentMotionSelection();timeline.highlightKey(selectedKey==null?null:clip(),selectedKey==null?-1:selectedKey.at);timeline.getLayoutParams().height=dp(project.timelineHeight());timeline.requestLayout();if(timelineViewport!=null){timelineViewport.getLayoutParams().height=dp(Math.min(150,project.timelineHeight()));timelineViewport.requestLayout();}for(EditorProject.Audio audio:project.audios)ensureWaveform(audio);int current=generation;ArrayList<EditorProject.Clip> sources=new ArrayList<>(project.clips);for(EditorProject.Overlay o:project.overlays)sources.add(o.clip);for(EditorProject.Clip c:sources)if(!timeline.thumbnails.containsKey(c.uri)){timeline.thumbnails.put(c.uri,null);EditorTimeline target=timeline;io.execute(()->{try{Bitmap bitmap=getContentResolver().loadThumbnail(Uri.parse(c.uri),new android.util.Size(160,100),null);main.post(()->{if(current==generation&&target==timeline){target.thumbnails.put(c.uri,bitmap);target.invalidate();}});}catch(Exception ignored){}});}}
    private void updateHistory(){if(undoButton!=null){undoButton.setEnabled(!undo.isEmpty());undoButton.setAlpha(undo.isEmpty()?.4f:1);redoButton.setEnabled(!redo.isEmpty());redoButton.setAlpha(redo.isEmpty()?.4f:1);}}
    private void clearMotionSelection(){selectedKeyOwner=null;selectedMotionKey=null;if(timeline!=null)timeline.highlightKey(null,-1);if(keyDeleteButton!=null)keyDeleteButton.setVisibility(View.GONE);}
    private EditorMotion.Key currentMotionSelection(){if(project==null||project.referenceClip()==null||selectedTrack.equals("Audio")||selectedTrack.equals("Effect"))return null;EditorProject.Clip c=clip();if(c==selectedKeyOwner&&c.keys.contains(selectedMotionKey))return selectedMotionKey;selectedKeyOwner=null;selectedMotionKey=null;return null;}
    private void selectMotionKey(long at){if(project==null||project.referenceClip()==null)return;pausePlayback();EditorProject.Clip c=clip();EditorMotion.Key key=EditorMotion.nearest(c,Math.max(0,at-selectedOffset()),40);if(key==null)return;transformKeyOwner=c;selectedKeyOwner=c;selectedMotionKey=key;if(livePreview!=null)livePreview.seekTo(selectedOffset()+key.at);position=selectedOffset()+key.at;tool="Keyframes";toolCategory=categoryForTool(tool);menuLevel=1;showCategoryTools();refreshTimeline();rebuildTools();if(keyDeleteButton!=null)keyDeleteButton.setVisibility(View.VISIBLE);}
    private void addMotionKey(){if(project==null||project.referenceClip()==null||selectedTrack.equals("Audio")||selectedTrack.equals("Effect"))return;pausePlayback();position=currentPosition();checkpoint();transformKeyOwner=clip();selectedKeyOwner=clip();selectedMotionKey=EditorMotion.put(selectedKeyOwner,keyTime(),objectTrack());committed();rebuildTools();}
    private void deleteMotionKey(){if(project==null||project.referenceClip()==null||selectedTrack.equals("Audio")||selectedTrack.equals("Effect"))return;pausePlayback();EditorProject.Clip c=clip();EditorMotion.Key selectedKey=currentMotionSelection();if(selectedKey==null)selectedKey=EditorMotion.nearest(c,keyTime(),40);if(selectedKey==null){notifyUser("Tap a timeline diamond to select a keyframe first");return;}checkpoint();EditorMotion.remove(c,selectedKey,objectTrack());clearMotionSelection();committed();rebuildTools();}
    private void clearObjectKeys(){if(project==null||project.referenceClip()==null||clip().keys.isEmpty())return;new AlertDialog.Builder(this).setTitle("Remove all keyframes from this layer?").setMessage("Keeps the current placement and the preset’s built-in animation. Other layers stay unchanged. You can undo this change.").setNegativeButton("Cancel",null).setPositiveButton("Remove keyframes",(d,w)->{pausePlayback();checkpoint();EditorMotion.clear(clip(),keyTime(),objectTrack());clearMotionSelection();committed();rebuildTools();}).show();}
    private boolean shouldAutoKey(){return !clip().keys.isEmpty()&&(clip().titleDesign==0||transformKeyOwner==clip());}
    private EditorMotion.Key autoKey(){if(!shouldAutoKey())return null;selectedKeyOwner=clip();selectedMotionKey=EditorMotion.put(selectedKeyOwner,keyTime(),objectTrack());if(timeline!=null)timeline.highlightKey(selectedKeyOwner,selectedMotionKey.at);return selectedMotionKey;}
    private void checkpoint(){try{undo.addLast(project.json().toString());while(undo.size()>40)undo.removeFirst();redo.clear();updateHistory();}catch(Exception e){notifyUser("Could not create undo step");}}
    private void save(){if(project!=null)try{project.save(this);}catch(Exception e){notifyUser("Draft could not save: "+e.getMessage());}}
    private void undo(){if(undo.isEmpty())return;try{redo.addLast(project.json().toString());project=EditorProject.from(undo.removeLast());selected=Math.min(selected,project.clips.size()-1);position=Math.min(position,project.duration());save();showEditor();}catch(Exception e){notifyUser("Undo failed");}}
    private void redo(){if(redo.isEmpty())return;try{undo.addLast(project.json().toString());project=EditorProject.from(redo.removeLast());selected=Math.min(selected,project.clips.size()-1);position=Math.min(position,project.duration());save();showEditor();}catch(Exception e){notifyUser("Redo failed");}}
    private void committed(){multiSelection.clear();if(!project.allowMainGaps)EditorEdits.closeMainGaps(project);if(gapButton!=null)gapButton.setText(project.allowMainGaps?"Gaps ON":"Gaps OFF");updateHistory();if(selectedAudio>=project.audios.size())selectedAudio=-1;if(project.referenceClip()==null){releasePlayer();position=0;save();showEmptyProject();return;}if(toolsPanel==null){save();showEditor();return;}if(project.clips.isEmpty()&&selectedTrack.equals("Video")){selectedOverlay=project.overlays.isEmpty()?-1:0;selectedCaption=selectedOverlay<0&&!project.captions.isEmpty()?0:-1;selectedTrack=selectedOverlay>=0?"Overlay":selectedCaption>=0?project.captions.get(selectedCaption).type:"Video";}selected=Math.max(0,Math.min(selected,project.clips.size()-1));if(selectedOverlay>=project.overlays.size()){selectedOverlay=-1;if(selectedTrack.equals("Overlay"))selectedTrack="Video";}if(selectedCaption>=project.captions.size()){selectedCaption=-1;if(objectTrack())selectedTrack="Video";}position=Math.min(position,project.duration());save();refreshTimeline();rebuildPreview(false);}
    private void schedulePreview(boolean immediate){if(!immediate){refreshLive();return;}main.removeCallbacks(previewUpdate);previewScheduled=true;main.post(previewUpdate);}
    private void rebuildPreview(boolean playNow){if(!editing||project==null||project.referenceClip()==null||exporting||previewStage==null||!active)return;
        try{if(livePreview==null){livePreview=new EditorLivePreview(this,new EditorLivePreview.Listener(){public void frame(){previewRendered=true;}public void error(String error){if(message!=null)message.setText(error);}});previewStage.addView(livePreview,0,new FrameLayout.LayoutParams(-1,-1));livePreview.bind(project);livePreview.seekTo(position);}else livePreview.bind(project);if(playNow)livePreview.play();message.setText("Live preview · "+project.clips.size()+" clips");main.removeCallbacks(tick);main.post(tick);}catch(Exception e){message.setText("Preview failed: "+e.getMessage());}
    }

    private void moveTimelineItem(String kind,int index,int row,long at){
        try{pausePlayback();if(kind.equals("Video")||kind.equals("Overlay")){int moved=EditorEdits.moveVideo(project,kind.equals("Video")?index:-1,kind.equals("Overlay")?index:-1,row,at);selectedCaption=-1;selectedTrack=row<0?"Video":"Overlay";selectedOverlay=row<0?-1:moved;if(row<0){selected=moved;at=project.offset(moved);}tool=row<0?"Trim":"Overlay";}
            else if(kind.equals("Effect")){if(index<0||index>=project.effects.size())return;EditorProject.EffectClip e=project.effects.get(index);long len=e.end-e.at;e.at=at;e.end=at+Math.max(200,len);e.track=row;selectedEffect=index;selectedTrack="Effect";selectedOverlay=-1;selectedCaption=-1;tool="Looks";}else if(kind.equals("Text")||kind.equals("Image")||kind.equals("Sticker")){EditorProject.Caption c=project.captions.remove(index);long length=c.end-c.at;c.at=at;c.end=at+length;c.track=row;project.captions.add(c);project.captions.sort((a,b)->Integer.compare(a.track,b.track));selectedCaption=project.captions.indexOf(c);selectedOverlay=-1;selectedTrack=kind;tool=kind.equals("Text")?"Text":"Transform";}
            else{if(index<0||index>=project.audios.size())return;EditorProject.Audio a=project.audios.get(index);a.at=at;a.track=row;selectedAudio=index;selectedTrack="Audio";selectedOverlay=-1;selectedCaption=-1;tool="Music";}

            position=at;committed();if(livePreview!=null)livePreview.seekTo(at);rebuildTools();
        }catch(IllegalArgumentException e){notifyUser(e.getMessage());refreshTimeline();}
    }

    private void selectTool(String next){if(project==null||exporting)return;if(next.equals("Blackout")){beginPrivacyDrawing();return;}cancelPrivacyDrawing();if(next.equals("My presets")){creatorLibrary(-3);return;}if(next.equals("Brand kit")){new EditorCreatorTools(this).brand();return;}if(next.equals("Captions")){new EditorCreatorTools(this).captions();return;}if(next.equals("Profession presets")){creatorLibrary(7);return;}if(next.equals("Tutorial graphics")){creatorLibrary(6);return;}if(next.equals("Save preset")){new EditorCreatorTools(this).savePreset();return;}if(next.equals("Safe areas")){new EditorCreatorTools(this).safeGuides();return;}if(next.equals("Cover")){creatorCover();return;}if(next.equals("Before & after")){new EditorCreatorTools(this).compare();return;}if(next.equals("Title library")){titleLibrary();return;}if(next.equals("Fullscreen")){fullscreenPreview();return;}toolCategory=categoryForTool(next);menuLevel=1;showCategoryTools();if(next.equals("Background remover ◆")){backgroundRemovalPrompt();return;}if(next.equals("Freeze")){freezeFrame();return;}if(next.equals("Image")){pickImage();return;}if(next.equals("Stickers")){stickerPicker();return;}if(next.equals("Looks")){selectedEffect=-1;selectedTrack="Effect";tool="Looks";rebuildTools();return;}
        if(next.equals("Add")){mediaPanel();return;}
        if(next.equals("Overlay")){tool=next;if(selectedOverlay<0||selectedOverlay>=project.overlays.size()){showOverlayImportScreen();return;}rebuildTools();if(placement!=null)placement.invalidate();return;}
        if(selectedTrack.equals("Overlay")&&selectedOverlay>=0&&selectedOverlay<project.overlays.size()){
            if(next.equals("Remove")){change(()->{project.overlays.remove(selectedOverlay);selectedOverlay=-1;selectedTrack="Video";tool="Overlay";});return;}
            if(next.equals("Split")){splitOverlay();return;}
            if(next.equals("Duplicate")){if(project.overlays.size()>=EditorProject.MAX_CLIPS){notifyUser("Project item limit reached");return;}try{checkpoint();EditorProject.Overlay duplicate=EditorProject.Overlay.from(project.overlays.get(selectedOverlay).json());duplicate.at=currentPosition();duplicate.track=project.videoTracks();project.overlays.add(duplicate);selectedOverlay=project.overlays.size()-1;selectedTrack="Overlay";tool="Overlay";committed();rebuildTools();}catch(Exception e){notifyUser("Could not duplicate overlay");}return;}
        }
        if(objectTrack()&&(next.equals("Trim")||next.equals("Remove")||next.equals("Split"))){if(next.equals("Remove")){if(selectedCaption>=0)change(()->{project.captions.remove(selectedCaption);selectedCaption=-1;selectedTrack="Video";tool="Trim";});return;}if(next.equals("Split")){splitCaption();return;}tool=selectedTrack.equals("Text")?"Text":"Transform";rebuildTools();return;}
        if(selectedTrack.equals("Audio")&&(next.equals("Trim")||next.equals("Remove")||next.equals("Split")||next.equals("Volume")||next.equals("Voice"))){if(next.equals("Remove")){if(audio()!=null)change(()->{project.audios.remove(selectedAudio);selectedAudio=-1;});return;}if(next.equals("Split")){splitAudio();return;}tool="Music";rebuildTools();return;}

        if(objectTrack()){
            if(next.equals("Duplicate")){if(selectedCaption>=0&&project.captions.size()<EditorProject.MAX_CLIPS)try{checkpoint();EditorProject.Caption duplicate=EditorProject.Caption.from(project.captions.get(selectedCaption).json());duplicate.track=selectedTrack.equals("Text")?project.textTracks():selectedTrack.equals("Image")?project.imageTracks():project.stickerTracks();duplicate.at=currentPosition();project.captions.add(duplicate);selectedCaption=project.captions.size()-1;committed();rebuildTools();}catch(Exception e){notifyUser("Could not duplicate layer");}return;}
            if(next.equals("Earlier")||next.equals("Later")){if(selectedCaption>=0)change(()->{EditorProject.Caption c=project.captions.get(selectedCaption);long duration=c.end-c.at;c.at=Math.max(0,c.at+(next.equals("Earlier")?-1000:1000));c.end=c.at+duration;});return;}
            if(Arrays.asList("Voice","Speed","Volume","Looks","Adjust").contains(next)){notifyUser("Select a video or PIP track for this tool");return;}
        }
        if(selectedTrack.equals("Audio")&&Arrays.asList("Duplicate","Earlier","Later","Rotate","Mirror","Crop","Mask","Transform","Animate","Voice","Speed","Looks","Adjust","Transition","Keyframes").contains(next)){notifyUser("Select a video or PIP track for this tool");return;}
        if(next.equals("Text")){selectedOverlay=-1;selectedTrack="Text";}
        if(next.equals("Music")){selectedOverlay=-1;selectedTrack="Audio";}
        if(selectedOverlay>=0&&(next.equals("Earlier")||next.equals("Later")||next.equals("Duplicate"))){notifyUser("Use Start at playhead to move the overlay; add another with Overlay");return;}
        if(next.equals("Split")){split();return;}
        if(next.equals("Duplicate")){if(project.clips.isEmpty())return;if(project.clips.size()>=EditorProject.MAX_CLIPS){notifyUser("Project item limit reached");return;}checkpoint();project.clips.add(selected+1,clip().copy());selected++;committed();rebuildTools();return;}
        if(next.equals("Remove")){if(project.clips.isEmpty())return;checkpoint();releasePlayer();EditorEdits.deleteMain(project,selected);selected=Math.min(selected,project.clips.size()-1);releasePlayer();position=project.offset(selected);committed();rebuildTools();return;}
        if(next.equals("Earlier")||next.equals("Later")){int target=selected+(next.equals("Earlier")?-1:1);if(target<0||target>=project.clips.size())return;checkpoint();EditorEdits.freezeMain(project);int left=Math.min(selected,target),right=Math.max(selected,target);long start=project.offset(left),gap=project.offset(right)-start-project.clips.get(left).length();Collections.swap(project.clips,selected,target);project.clips.get(left).timelineAt=start;project.clips.get(right).timelineAt=start+project.clips.get(left).length()+gap;selected=target;releasePlayer();position=project.offset(selected);committed();rebuildTools();return;}
        if(next.equals("Rotate")){checkpoint();EditorMotion.Key key=autoKey();if(key==null)clip().rotation=(clip().rotation+1)%4;else key.rotation=(key.rotation+90)%360;committed();return;}
        if(next.equals("Mirror")){checkpoint();clip().mirror=!clip().mirror;committed();return;}
        tool=next;rebuildTools();if(placement!=null)placement.invalidate();
    }
    private void addEffectClip(){if(project.effects.size()>=EditorProject.MAX_CLIPS){notifyUser("Project item limit reached");return;}checkpoint();EditorProject.EffectClip fx=new EditorProject.EffectClip();fx.preset=1;fx.at=Math.min(position,Math.max(0,project.duration()-200));fx.end=Math.min(project.duration(),fx.at+3000);if(fx.end<=fx.at)fx.end=fx.at+200;fx.track=project.effectTracks();project.effects.add(fx);selectedEffect=project.effects.size()-1;selectedTrack="Effect";selectedOverlay=selectedCaption=-1;position=fx.at;committed();rebuildTools();}
    private void splitCaption(){if(selectedCaption<0)return;EditorProject.Caption left=project.captions.get(selectedCaption);long at=position;if(at<=left.at||at>=left.end){notifyUser("Position the playhead inside the selected text layer");return;}if(project.captions.size()>=EditorProject.MAX_CLIPS){notifyUser("Project item limit reached");return;}try{checkpoint();EditorProject.Caption right=EditorProject.Caption.from(left.json());right.at=at;left.end=at;project.captions.add(selectedCaption+1,right);selectedCaption++;committed();rebuildTools();}catch(Exception e){notifyUser("Text split failed");}}
    private void splitOverlay(){if(project.overlays.size()>=EditorProject.MAX_CLIPS){notifyUser("Project item limit reached");return;}EditorProject.Overlay left=project.overlays.get(selectedOverlay);long at=currentPosition(),source=EditTiming.sourceTime(left.clip.start,left.clip.end,left.clip.speed,at-left.at);if(!EditTiming.canSplit(left.clip.start,left.clip.end,source)){notifyUser("Position the playhead inside the selected overlay, 0.2 seconds from its edges");return;}try{checkpoint();EditorProject.Overlay right=EditorProject.Overlay.from(left.json());left.clip.end=source;right.clip.start=source;right.at=at;long cut=left.clip.length();right.clip.textStart=Math.max(0,right.clip.textStart-cut);if(right.clip.textEnd!=Long.MAX_VALUE)right.clip.textEnd=Math.max(1,right.clip.textEnd-cut);project.overlays.add(selectedOverlay+1,right);selectedOverlay++;committed();rebuildTools();}catch(Exception e){notifyUser("Overlay split failed");}}
    private void split(){if(project.clips.isEmpty())return;if(project.clips.size()>=EditorProject.MAX_CLIPS){notifyUser("Project item limit reached");return;}long at=currentPosition();int index=0;while(index<project.clips.size()-1&&at>=project.offset(index+1))index++;EditorProject.Clip c=project.clips.get(index);if(at<project.offset(index)||at>=project.offset(index)+c.length()){notifyUser("Position the playhead inside a video clip");return;}long source=EditTiming.sourceTime(c.start,c.end,c.speed,at-project.offset(index));if(!EditTiming.canSplit(c.start,c.end,source)){notifyUser("Move the playhead at least 0.2 seconds from a clip edge");return;}checkpoint();EditorProject.Clip right=c.copy();right.timelineAt=at;right.start=source;c.end=source;long cut=c.length();right.textStart=Math.max(0,right.textStart-cut);if(right.textEnd!=Long.MAX_VALUE)right.textEnd=Math.max(1,right.textEnd-cut);project.clips.add(index+1,right);selected=index+1;position=at;committed();rebuildTools();}
    private void findSceneCuts(){if(project==null||project.clips.isEmpty()||exporting)return;pausePlayback();final EditorProject target=project;final int token=generation;final int clipIndex=selected;EditorProject.Clip source=clip();long in=source.start,out=source.end;double speed=source.speed;long timelineAt=project.offset(clipIndex);notifyUser("Scanning a few frames for likely cuts…");io.execute(()->{ArrayList<Long> cuts=new ArrayList<>();String failure="";MediaMetadataRetriever retriever=new MediaMetadataRetriever();try{retriever.setDataSource(this,Uri.parse(source.uri));long duration=Math.max(0,out-in),step=Math.max(750,Math.min(2500,duration/45));Bitmap previous=null;long previousAt=-1;for(long local=step;local<duration;local+=step){Bitmap frame=retriever.getFrameAtTime((in+local)*1000,MediaMetadataRetriever.OPTION_CLOSEST_SYNC);if(frame==null)continue;Bitmap small=Bitmap.createScaledBitmap(frame,24,14,true);if(small!=frame)frame.recycle();if(previous!=null){double delta=frameDifference(previous,small);if(delta>.24){long at=timelineAt+Math.round((local/speed));if(at>timelineAt+250&&at<timelineAt+source.length()-250&&(cuts.isEmpty()||at-cuts.get(cuts.size()-1)>500))cuts.add(at);}}if(previous!=null)previous.recycle();previous=small;previousAt=local;}if(previous!=null)previous.recycle();if(cuts.size()>60)cuts.subList(60,cuts.size()).clear();}catch(Exception e){failure=e.getMessage()==null?"Could not analyze this video":e.getMessage();}finally{try{retriever.release();}catch(Exception ignored){}}final String error=failure;main.post(()->{if(project!=target||token!=generation||isFinishing())return;if(!error.isEmpty()){notifyUser("Scene scan failed: "+error);return;}if(cuts.isEmpty()){notifyUser("No strong scene changes found. Try a video with clear cuts.");return;}ArrayList<String> labels=new ArrayList<>();for(Long cut:cuts)labels.add(time(cut));new AlertDialog.Builder(this).setTitle("Likely scene cuts · "+cuts.size()).setMessage("Found by comparing sampled frames on this device. Review the timestamps, then apply splits individually.").setItems(labels.toArray(new String[0]),(dialog,which)->splitAt(cuts.get(which))).setPositiveButton("Split at all",(dialog,which)->splitAtAll(cuts)).setNegativeButton("Cancel",null).show();});});}
    private double frameDifference(Bitmap a,Bitmap b){int w=Math.min(a.getWidth(),b.getWidth()),h=Math.min(a.getHeight(),b.getHeight());long total=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int p=a.getPixel(x,y),q=b.getPixel(x,y);int lum=Math.abs(((p>>16)&255)-((q>>16)&255))+Math.abs(((p>>8)&255)-((q>>8)&255))+Math.abs((p&255)-(q&255));total+=lum;}return total/(double)Math.max(1,w*h*3*255);}
    private void splitAtAll(ArrayList<Long> cuts){if(project==null)return;checkpoint();int index=selected;for(Long cut:cuts){long offset=project.offset(index);while(index<project.clips.size()-1&&cut>=project.offset(index+1)){index++;offset=project.offset(index);}if(index<0||index>=project.clips.size())continue;EditorProject.Clip left=project.clips.get(index);long relative=cut-offset;if(relative<200||relative>left.length()-200||project.clips.size()>=EditorProject.MAX_CLIPS)continue;long source=EditTiming.sourceTime(left.start,left.end,left.speed,relative);if(!EditTiming.canSplit(left.start,left.end,source))continue;EditorProject.Clip right=left.copy();right.timelineAt=cut;right.start=source;left.end=source;project.clips.add(index+1,right);index++;}selected=Math.min(index,project.clips.size()-1);position=project.offset(selected);committed();rebuildTools();notifyUser("Scene cuts added to the timeline");}
    private void splitAt(long at){if(project==null||project.clips.isEmpty())return;int index=0;while(index<project.clips.size()-1&&at>=project.offset(index+1))index++;EditorProject.Clip left=project.clips.get(index);long relative=at-project.offset(index);if(relative<200||relative>left.length()-200||project.clips.size()>=EditorProject.MAX_CLIPS)return;long source=EditTiming.sourceTime(left.start,left.end,left.speed,relative);if(!EditTiming.canSplit(left.start,left.end,source))return;checkpoint();EditorProject.Clip right=left.copy();right.timelineAt=at;right.start=source;left.end=source;long cut=left.length();right.textStart=Math.max(0,right.textStart-cut);if(right.textEnd!=Long.MAX_VALUE)right.textEnd=Math.max(1,right.textEnd-cut);project.clips.add(index+1,right);selected=index+1;selectedTrack="Video";selectedOverlay=-1;selectedCaption=-1;position=at;committed();rebuildTools();}
    private interface NumberChange{double value(double n);}
    private void slider(String title,double low,double high,double initial,String unit,NumberChange change){
        TextView readout=text(title+"  "+numeric(initial,unit),11,TEXT);toolsPanel.addView(readout,new LinearLayout.LayoutParams(-1,dp(24)));SeekBar bar=new SeekBar(this);bar.setMax(1000);bar.setProgress((int)Math.round((initial-low)*1000/(high-low)));bar.setContentDescription(title);bar.setProgressTintList(android.content.res.ColorStateList.valueOf(ACCENT));bar.setThumbTintList(android.content.res.ColorStateList.valueOf(ACCENT));toolsPanel.addView(bar,new LinearLayout.LayoutParams(-1,dp(36)));
        bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){checkpoint();pausePlayback();}public void onProgressChanged(SeekBar b,int p,boolean user){if(!user)return;double value=low+(high-low)*p/1000;double actual=change.value(value);readout.setText(title+"  "+numeric(actual,unit));int corrected=(int)Math.round((actual-low)*1000/(high-low));if(corrected!=p)b.setProgress(corrected);schedulePreview(false);}public void onStopTrackingTouch(SeekBar b){committed();}});
    }
    private String numeric(double n,String unit){if(unit.equals("time"))return time(Math.round(n));if(unit.equals("%"))return Math.round(n*100)+"%";if(unit.equals("x"))return String.format(Locale.US,"%.2fx",n);return String.valueOf(Math.round(n));}
    private void chips(String[] names,java.util.function.IntConsumer action){HorizontalScrollView scroll=new HorizontalScrollView(this);scroll.setHorizontalScrollBarEnabled(false);LinearLayout choices=new LinearLayout(this);for(int i=0;i<names.length;i++){final int index=i;choices.addView(button(names[i],()->action.accept(index)));}scroll.addView(choices);toolsPanel.addView(scroll,new LinearLayout.LayoutParams(-1,dp(42)));}
