    private void freezeFrame(){if(project==null||project.clips.isEmpty()){notifyUser("Select a video clip first");return;}long at=currentPosition();int index=0;while(index<project.clips.size()-1&&at>=project.offset(index+1))index++;EditorProject.Clip source=project.clips.get(index);if(at<project.offset(index)||at>=project.offset(index)+source.length()){notifyUser("Place the playhead over a video frame");return;}if(project.captions.size()>=EditorProject.MAX_CLIPS){notifyUser("Project item limit reached");return;}long sourceMs=source.start+Math.round((at-project.offset(index))*source.speed);int token=generation;io.execute(()->{File output=null;try{MediaMetadataRetriever retriever=new MediaMetadataRetriever();retriever.setDataSource(this,Uri.parse(source.uri));Bitmap frame=retriever.getFrameAtTime(sourceMs*1000,MediaMetadataRetriever.OPTION_CLOSEST);retriever.release();if(frame==null)throw new IOException("Could not decode this frame");File dir=new File(getFilesDir(),"editor-freezes");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Storage unavailable");output=new File(dir,"freeze-"+UUID.randomUUID()+".png");try(FileOutputStream out=new FileOutputStream(output)){frame.compress(Bitmap.CompressFormat.PNG,100,out);}frame.recycle();File result=output;main.post(()->{if(token!=generation||isFinishing()){result.delete();return;}checkpoint();EditorProject.Caption caption=new EditorProject.Caption();caption.type="Image";caption.style=source.copy();caption.style.keys.clear();caption.style.imageUri=result.getAbsolutePath();caption.style.fillFrame=true;caption.style.text="";caption.style.textReveal=0;caption.style.opacity=1;caption.style.cropX=caption.style.cropY=0;caption.style.zoom=1;caption.style.stretchX=caption.style.stretchY=1;caption.style.rotation=0;caption.style.mirror=false;caption.style.mask=0;caption.style.fade=0;caption.style.animation=0;caption.style.textPlaced=true;caption.style.textX=caption.style.textY=0;caption.track=project.imageTracks();caption.at=at;caption.end=at+2000;project.captions.add(caption);selectedCaption=project.captions.size()-1;selectedOverlay=-1;selectedTrack="Image";tool="Transform";position=at;committed();rebuildTools();notifyUser("2-second freeze frame added as an editable layer");});}catch(Exception e){if(output!=null)output.delete();main.post(()->notifyUser("Freeze frame failed: "+e.getMessage()));}});}
