    private void fontPicker(EditorProject.Clip c){ArrayList<String> names=new ArrayList<>(Arrays.asList(FONT_NAMES)),values=new ArrayList<>(Arrays.asList(FONT_VALUES));EditorFontLibrary.appendInstalled(this,names,values);File folder=new File(getFilesDir(),"fonts");File[] imported=folder.listFiles((dir,n)->n.endsWith(".font"));if(imported!=null)for(File file:imported){names.add("Imported · "+file.getName().substring(0,Math.min(8,file.getName().length())));values.add("file:"+file.getAbsolutePath());}if(c.font.startsWith("file:")&&!values.contains(c.font)){names.add("Imported font");values.add(c.font);}String[] labels=names.toArray(new String[0]),fontsValue=values.toArray(new String[0]);LinearLayout row=new LinearLayout(this);Spinner fonts=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels){public View getView(int at,View v,android.view.ViewGroup parent){TextView t=(TextView)super.getView(at,v,parent);t.setTextColor(TEXT);t.setTypeface(EditorFonts.face(fontsValue[at],Typeface.NORMAL));return t;}};fonts.setAdapter(adapter);int current=Math.max(0,values.indexOf(c.font));fonts.setSelection(current);fonts.setContentDescription("Font family");row.addView(button("‹",()->fonts.setSelection((fonts.getSelectedItemPosition()+fontsValue.length-1)%fontsValue.length)));row.addView(fonts,new LinearLayout.LayoutParams(0,dp(48),1));row.addView(button("›",()->fonts.setSelection((fonts.getSelectedItemPosition()+1)%fontsValue.length)));fonts.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int at,long id){if(!c.font.equals(fontsValue[at])){checkpoint();c.font=fontsValue[at];committed();}}});toolsPanel.addView(row);chips(new String[]{"+ Download fonts","+ Import TTF / OTF"},i->{if(i==0)EditorFontLibrary.show(this,value->{checkpoint();c.font=value;committed();rebuildTools();});else pickFont();});}
