    private void runSubjectTracking(){if(project==null||project.clips.isEmpty()||selectedOverlay>=0||!selectedTrack.equals("Video"))return;EditorProject.Clip selectedClip=clip();int clipIndex=selected;EditorProject targetProject=project;long sourceStart=selectedClip.start,sourceDuration=selectedClip.end-selectedClip.start,timelineLength=selectedClip.length();double speed=selectedClip.speed;Uri uri=Uri.parse(selectedClip.uri);pausePlayback();ProgressDialog progress=new ProgressDialog(this);progress.setTitle("Tracking subject");progress.setMessage("Analyzing sampled frames on this phone…");progress.setIndeterminate(true);progress.setCancelable(false);progress.show();io.execute(()->{ArrayList<EditorAi.SubjectPoint> points=null;String failure="";try{points=EditorAi.trackPerson(this,uri,sourceStart,sourceDuration);}catch(Exception e){failure=e.getMessage()==null?"Subject tracking failed":e.getMessage();}ArrayList<EditorAi.SubjectPoint> result=points;String error=failure;main.post(()->{if(progress.isShowing())progress.dismiss();if(isFinishing()||project!=targetProject||clipIndex>=project.clips.size())return;if(!error.isEmpty()){new AlertDialog.Builder(this).setTitle("Subject tracking").setMessage(error).setPositiveButton("OK",null).show();return;}if(result==null||result.size()<2){notifyUser("A clear person was not found in enough sampled frames");return;}checkpoint();EditorProject.Clip c=project.clips.get(clipIndex);c.keys.clear();for(EditorAi.SubjectPoint point:result){EditorMotion.Key key=new EditorMotion.Key();key.at=Math.max(0,Math.min(timelineLength,Math.round(point.at/speed)));key.x=EditorProject.bound((.5-point.x)*1.8,-.9,.9);key.y=EditorProject.bound((point.y-.5)*1.8,-.9,.9);key.scale=EditorProject.bound(Math.max(1,.78/Math.max(.15,point.height)),1,1.8);c.keys.add(key);}c.keys.sort((a,b)->Long.compare(a.at,b.at));selected=clipIndex;selectedTrack="Video";selectedOverlay=selectedCaption=-1;tool="Transform";position=project.offset(selected)+Math.min(timelineLength-1,Math.round(result.get(0).at/speed));committed();aiScreen=false;editing=true;showEditor();notifyUser("Subject framing added · "+result.size()+" editable keyframes");});});}
