    private void backgroundRemovalPrompt(){aiTargetCaption=selectedPhotoCaption();boolean selectedPhoto=aiTargetCaption>=0,ready=EditorAi.installed(this);String action=selectedPhoto?"Remove the background from the selected photo and replace that image layer in place.":"Choose a photo after the model is ready; its cutout will be added as a transparent image layer.";String size=ready?readableBytes(EditorAi.modelFile(this).length()):"about 249 KB";String message=ready?"The model is already downloaded ("+size+"). This photo effect runs offline using one CPU thread. "+action:"This AI effect needs the MediaPipe Selfie Segmentation model ("+size+"). Internet is required for the one-time download; afterward processing is offline. The model uses one CPU thread to limit battery and heat. "+action+" Download now?";AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle(ready?"Background remover ◆":"Download AI model? ◆").setMessage(message).setNegativeButton("Cancel",null);if(ready)dialog.setPositiveButton(selectedPhoto?"Remove background":"Choose photo",(d,w)->{if(selectedPhoto)removePhotoBackgroundFromLayer(aiTargetCaption);else pickAiImage();}).setNeutralButton("Remove model",(d,w)->removeAiModel());else dialog.setPositiveButton("Download · "+size,(d,w)->startAiDownload());dialog.show();}
    private void startAiDownload(){if(exporting)return;int targetCaption=aiTargetCaption;EditorProject targetProject=project;cancelAiDownload=false;ProgressDialog progress=new ProgressDialog(this);aiDownloadDialog=progress;progress.setTitle("Downloading AI model");progress.setMessage("MediaPipe Selfie Segmentation · about 249 KB · Internet required");progress.setProgressStyle(ProgressDialog.STYLE_HORIZONTAL);progress.setMax(1000);progress.setCancelable(true);progress.setOnCancelListener(d->cancelAiDownload=true);progress.setButton(AlertDialog.BUTTON_NEGATIVE,"Cancel",(d,w)->{cancelAiDownload=true;});progress.show();io.execute(()->{String failure="";try{EditorAi.download(this,(read,total)->{if(cancelAiDownload)return false;main.post(()->{if(aiDownloadDialog==progress&&progress.isShowing()){if(total>0){progress.setIndeterminate(false);progress.setProgress((int)Math.min(1000,read*1000/total));progress.setMessage("Downloaded "+readableBytes(read)+" of "+readableBytes(total));}else progress.setIndeterminate(true);}});return !cancelAiDownload;});}catch(Exception e){failure=e.getMessage()==null?"Download failed":e.getMessage();}final String error=failure;main.post(()->{if(aiDownloadDialog==progress){aiDownloadDialog=null;if(progress.isShowing())progress.dismiss();}if(isFinishing())return;if(error.isEmpty()){notifyUser("AI person model ready · "+readableBytes(EditorAi.modelFile(this).length()));if(targetCaption==-2&&project==targetProject)runSubjectTracking();else if(targetCaption>=0&&project==targetProject)removePhotoBackgroundFromLayer(targetCaption);else pickAiImage();}else if(!error.toLowerCase(Locale.US).contains("cancel"))new AlertDialog.Builder(this).setTitle("Model download").setMessage(error+"\nCheck your internet connection and try again.").setPositiveButton("OK",null).show();});});}
