    private void removePhotoBackgroundFromLayer(int captionIndex){if(project==null||captionIndex<0||captionIndex>=project.captions.size()){notifyUser("Select a photo layer first");return;}String path=project.captions.get(captionIndex).style.imageUri;if(path==null||path.isEmpty()){notifyUser("The selected layer is not a photo");return;}Uri uri=Uri.parse(path);if(uri.getScheme()==null)uri=Uri.fromFile(new File(path));processPhotoCutout(uri,captionIndex);}
