    private void processPhotoCutout(Uri uri,int targetCaption){if(project==null||!EditorAi.installed(this)){notifyUser("Download the photo cutout model first");return;}EditorProject target=project;long at=position;int token=generation;notifyUser("Removing photo background on this phone… This may take a moment.");io.execute(()->{File result=null;String failure="";try{result=EditorAi.removePhotoBackground(this,uri);}catch(Exception e){failure=e.getMessage()==null?"Photo cutout failed":e.getMessage();}File output=result;String error=failure;main.post(()->{if(token!=generation||project!=target||isFinishing()){if(output!=null)output.delete();return;}if(!error.isEmpty()){new AlertDialog.Builder(this).setTitle("Photo background remover").setMessage(error).setPositiveButton("OK",null).show();return;}if(targetCaption>=0&&targetCaption<project.captions.size()){checkpoint();EditorProject.Caption layer=project.captions.get(targetCaption);String old=layer.style.imageUri;layer.style.imageUri=output.getAbsolutePath();layer.type="Image";selectedCaption=targetCaption;selectedOverlay=-1;selectedTrack="Image";tool="Transform";toolCategory="Image";aiScreen=false;editing=true;committed();rebuildTools();rebuildPreview(false);notifyUser("Background removed · photo layer updated");}else{aiScreen=false;editing=true;showEditor();addObject(output.getAbsolutePath(),"Photo cutout",at);notifyUser("Background removed · transparent photo added to the timeline");}});});}
    private void pickImage(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivityForResult(intent,42);}catch(ActivityNotFoundException e){notifyUser("No image picker available");}}
    private void importImage(Uri uri){EditorProject target=project;long at=position;io.execute(()->{try{ImageDecoder.Source source=ImageDecoder.createSource(getContentResolver(),uri);Bitmap bitmap=ImageDecoder.decodeBitmap(source,(decoder,info,src)->{int w=info.getSize().getWidth(),h=info.getSize().getHeight();double scale=Math.min(1,2048.0/Math.max(w,h));decoder.setTargetSize(Math.max(1,(int)(w*scale)),Math.max(1,(int)(h*scale)));decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);});File dir=new File(getFilesDir(),"editor-images");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Image storage unavailable");File file=new File(dir,UUID.randomUUID()+".png");try(FileOutputStream out=new FileOutputStream(file)){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();main.post(()->{if(project==target&&!isFinishing()){addObject(file.getAbsolutePath(),"Image",at);}});}catch(Exception e){main.post(()->notifyUser("Cannot import image: "+e.getMessage()));}});}
    private void addObject(String image,String label,long at){if(project.captions.size()>=EditorProject.MAX_CLIPS){notifyUser("Project item limit reached");return;}checkpoint();EditorProject.Caption c=new EditorProject.Caption();c.type="Image";c.style=project.referenceClip()==null?new EditorProject.Clip("","Canvas",5000):project.referenceClip().copy();c.style.keys.clear();c.style.privacyBlackout=false;c.style.imageUri=image;c.style.text=label;c.style.zoom=1;c.style.stretchX=c.style.stretchY=1;c.style.cropX=c.style.cropY=0;c.style.rotation=c.style.mask=c.style.animation=c.style.transitionIn=c.style.transitionOut=0;c.style.fadeIn=c.style.fadeOut=c.style.fade=0;c.style.backgroundEnabled=c.style.shadowEnabled=false;c.style.textX=c.style.textY=0;c.style.textPlaced=true;c.style.textSize=120;c.at=at;c.end=Math.max(at+5000,project.duration());c.track=project.imageTracks();project.captions.add(c);selectedCaption=project.captions.size()-1;selectedOverlay=-1;selectedTrack="Image";tool="Transform";committed();rebuildTools();}
    private void addSticker(String sticker,long at){if(project.captions.size()>=EditorProject.MAX_CLIPS){notifyUser("Project item limit reached");return;}checkpoint();EditorProject.Caption c=new EditorProject.Caption();c.type="Sticker";c.style=project.referenceClip()==null?new EditorProject.Clip("","Canvas",5000):project.referenceClip().copy();c.style.keys.clear();c.style.titleDesign=0;c.style.privacyBlackout=false;c.style.text=sticker;c.style.imageUri="";c.style.zoom=1;c.style.textSize=180;c.style.textColor=Color.WHITE;c.style.textX=c.style.textY=0;c.style.textPlaced=true;c.at=at;c.end=Math.max(at+2000,project.duration());c.track=project.stickerTracks();project.captions.add(c);selectedCaption=project.captions.size()-1;selectedOverlay=-1;selectedTrack="Sticker";tool="Transform";committed();rebuildTools();}
