    private void creatorCover(){if(creatorDialog!=null)creatorDialog.dismiss();if(livePreview==null||project==null||project.referenceClip()==null){notifyUser("Open your video and move the playhead to a cover frame first");return;}pausePlayback();livePreview.showGuides(false);if(placement!=null)placement.setVisibility(View.INVISIBLE);main.postDelayed(()->{if(livePreview==null||isFinishing())return;android.graphics.Rect area=livePreview.captureRect();if(area.width()<2||area.height()<2){livePreview.showGuides(true);if(placement!=null)placement.setVisibility(View.VISIBLE);return;}float factor=Math.min(1,1280f/Math.max(area.width(),area.height()));Bitmap frame=Bitmap.createBitmap(Math.max(2,Math.round(area.width()*factor)),Math.max(2,Math.round(area.height()*factor)),Bitmap.Config.ARGB_8888);android.view.PixelCopy.request(getWindow(),area,frame,result->{if(livePreview!=null)livePreview.showGuides(true);if(placement!=null)placement.setVisibility(View.VISIBLE);if(result!=android.view.PixelCopy.SUCCESS||isFinishing()){frame.recycle();notifyUser("Could not capture this frame. Play or seek the video, then try again.");return;}new EditorCoverDesigner(this,frame).show();},main);},180);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null){importingOverlay=false;if(audioImportScreen)showAudioImportScreen();else if(overlayImportScreen)showOverlayImportScreen();else if(editing)rebuildPreview(false);return;}
        if(request==560){if(data.getData()!=null)new EditorCreatorTools(this).logo(data.getData());return;}if(request==561){if(data.getData()!=null)new EditorCreatorTools(this).importSrt(data.getData());return;}if(request==45){Uri photo=data.getData();if(photo!=null){try{getContentResolver().takePersistableUriPermission(photo,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}previewPhotoOverlay(photo);}return;}
        if(request==42){if(data.getData()!=null)importImage(data.getData());return;}if(request==43){if(data.getData()!=null)importFont(data.getData());return;}if(request==44){Uri photo=data.getData();if(photo!=null){try{getContentResolver().takePersistableUriPermission(photo,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}removePhotoBackground(photo);}return;}
        ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());
        for(Uri uri:uris)try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}
        if(request==40){boolean overlay=importingOverlay||overlayImportScreen;importingOverlay=false;previewImports(uris,false,importAsNew,overlay);}else if(request==41&&!uris.isEmpty()){
            previewImports(uris,true,false,false);

        }
    }
    private EditorProject.Audio audio(){return selectedAudio>=0&&selectedAudio<project.audios.size()?project.audios.get(selectedAudio):null;}
