    private void splitAudio(){if(project.audios.size()>=EditorProject.MAX_CLIPS){notifyUser("Project audio limit reached");return;}EditorProject.Audio a=audio();if(a==null)return;long cut=currentPosition()-a.at;if(cut<100||cut>a.length()-100){notifyUser("Place the playhead inside the selected audio");return;}try{checkpoint();EditorProject.Audio right=EditorProject.Audio.from(a.json());right.start=a.start+cut;right.at=a.at+cut;a.end=right.start;project.audios.add(right);selectedAudio=project.audios.size()-1;committed();rebuildTools();}catch(Exception e){notifyUser("Could not split audio");}}
    private void importAudio(List<Uri> uris){if(project==null){notifyUser("Start a video project before adding audio");audioImportScreen=false;returnToEditor();return;}EditorProject target=project;long at=position;notifyUser("Importing audio…");io.execute(()->{ArrayList<EditorProject.Audio> imported=new ArrayList<>();String error="";for(Uri uri:uris){try{imported.add(EditorAudio.importFile(this,uri,displayName(uri)));}catch(Exception e){error=e.getMessage()==null?"This audio could not be opened. Try another local audio file.":e.getMessage();}}String failure=error;main.post(()->{if(project!=target||isFinishing())return;if(!imported.isEmpty()){checkpoint();for(EditorProject.Audio a:imported){if(project.audios.size()>=EditorProject.MAX_CLIPS)break;a.at=at;a.track=project.audioTracks();project.audios.add(a);}selectedAudio=project.audios.size()-1;selectedTrack="Audio";selectedCaption=selectedOverlay=-1;tool="Music";if(audioImportScreen){save();showAudioImportScreen();}else{committed();rebuildTools();}}else if(audioImportScreen){audioImportScreen=false;editing=true;showEditor();}if(!failure.isEmpty())new AlertDialog.Builder(this).setTitle("Audio import").setMessage(failure).setPositiveButton("OK",null).show();});});}
    private void loadOverlay(List<Uri> uris){if(uris.isEmpty()||project==null)return;EditorProject target=project;long at=position;io.execute(()->{try{EditorProject.Clip c=readClip(uris.get(0));main.post(()->{if(project!=target||isFinishing()||target.overlays.size()>=EditorProject.MAX_CLIPS)return;checkpoint();EditorProject.Overlay o=new EditorProject.Overlay();o.clip=c;o.track=project.videoTracks();o.at=Math.min(at,project.duration()-200);o.clip.end=Math.min(o.clip.end,o.clip.start+Math.max(200,project.videoDuration()-o.at));project.overlays.add(o);selectedOverlay=project.overlays.size()-1;selectedTrack="Overlay";tool="Overlay";save();refreshTimeline();rebuildTools();rebuildPreview(false);});}catch(Exception e){main.post(()->notifyUser("Cannot import overlay: "+e.getMessage()));}});}
    private void loadVideos(List<Uri> uris,boolean fresh){if(uris.isEmpty())return;int current=generation;notifyUser("Reading video…");io.execute(()->{ArrayList<EditorProject.Clip> clips=new ArrayList<>();String error="";for(Uri uri:uris){if(clips.size()>=EditorProject.MAX_CLIPS)break;try{clips.add(readClip(uri));}catch(Exception e){error="Some videos could not be opened: "+e.getMessage();}}final String failure=error;main.post(()->{if(current!=generation||isFinishing()||isDestroyed())return;if(!failure.isEmpty())notifyUser(failure);if(clips.isEmpty())return;if(fresh||project==null){selectedCaption=-1;selectedTrack="Video";selectedOverlay=-1;project=new EditorProject();undo.clear();redo.clear();selected=0;position=0;}else checkpoint();int room=EditorProject.MAX_CLIPS-project.clips.size();if(clips.size()>room)notifyUser("Project item limit reached");for(int i=0;i<Math.min(room,clips.size());i++)project.clips.add(clips.get(i));save();showEditor();});});}
    private String displayName(Uri uri){try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.isNull(0)?"Imported clip":c.getString(0);}return "Imported clip";}
    private long mediaDuration(Uri uri)throws Exception{MediaMetadataRetriever r=new MediaMetadataRetriever();try{r.setDataSource(this,uri);long duration=Long.parseLong(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));if(duration<200)throw new IOException("Media is too short");return duration;}finally{r.release();}}
    private EditorProject.Clip readClip(Uri uri)throws Exception{MediaMetadataRetriever r=new MediaMetadataRetriever();try{r.setDataSource(this,uri);if(!"yes".equals(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_VIDEO)))throw new IOException("No readable video track");EditorProject.Clip c=new EditorProject.Clip(uri.toString(),displayName(uri),Long.parseLong(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION)));c.width=Integer.parseInt(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH));org.json.JSONObject notes=CreatorNotes.read(this,uri.toString());c.audioSyncMs=notes.optInt("audioSyncMs");if(notes.optJSONArray("markers")!=null)c.markers=notes.optJSONArray("markers");c.height=Integer.parseInt(r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));String rotation=r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION);if(rotation!=null&&Integer.parseInt(rotation)%180!=0){int swap=c.width;c.width=c.height;c.height=swap;}return c;}finally{r.release();}}
    private static String time(long ms){long tenths=Math.max(0,ms)/100;return String.format(Locale.US,"%02d:%02d.%d",tenths/600,(tenths/10)%60,tenths%10);}

    private void exportSetup(){if(project==null||project.referenceClip()==null||exporting)return;LinearLayout panel=column();EditText name=new EditText(this);name.setText(project.name);name.setSingleLine();name.setTextColor(TEXT);name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(64)});panel.addView(name);
        RadioGroup quality=new RadioGroup(this);for(int height:new int[]{720,1080}){RadioButton radio=new RadioButton(this);radio.setId(View.generateViewId());radio.setText(height==720?"720p · smaller file":"1080p · better detail");radio.setTextColor(TEXT);quality.addView(radio);if(project.height==height)radio.setChecked(true);}panel.addView(quality);panel.addView(text("Exports an MP4 with your edits and mixed audio. Keep the editor open until it finishes. Originals are preserved.",12,MUTED));
        new AlertDialog.Builder(this).setTitle("Export your story").setView(panel).setPositiveButton("Export MP4",(d,w)->{project.name=name.getText().toString().trim();if(project.name.isEmpty())project.name="My story";project.height=quality.getCheckedRadioButtonId()==quality.getChildAt(0).getId()?720:1080;save();startExport();}).setNeutralButton("Export audio…",(d,w)->audioFormatDialog()).setNegativeButton("Cancel",null).show();
    }
    private void selectionMenu(){new AlertDialog.Builder(this).setTitle("Timeline selection").setItems(new String[]{"Select this track","Select all tracks","Choose individual items","Create compound from all tracks","Unpack selected compound","Clear selection","Detach audio from selected video"},(d,which)->{if(which==0){int row=selectedTrack.equals("Audio")&&audio()!=null?audio().track:selectedOverlay>=0?project.overlays.get(selectedOverlay).track:selectedCaption>=0?project.captions.get(selectedCaption).track:selectedTrack.equals("Effect")&&selectedEffect>=0?project.effects.get(selectedEffect).track:0;multiSelection.track(project,selectedTrack,row);selectionActions();}else if(which==1){multiSelection.all(project);selectionActions();}else if(which==2)chooseTimelineItems();else if(which==3)createCompoundPrompt();else if(which==4)unpackCompound();else if(which==6)detachAudio();else{multiSelection.clear();refreshTimeline();}}).setNegativeButton("Close",null).show();}
    private void chooseTimelineItems(){ArrayList<Object> items=new ArrayList<>();ArrayList<String> labels=new ArrayList<>();for(EditorProject.Clip c:project.clips){items.add(c);labels.add("Video · "+c.name);}for(EditorProject.Overlay o:project.overlays){items.add(o);labels.add("Overlay "+(o.track+1)+" · "+o.clip.name);}for(EditorProject.Caption c:project.captions){items.add(c);labels.add(c.type+" "+(c.track+1)+" · "+c.style.text);}for(EditorProject.Audio a:project.audios){items.add(a);labels.add("Audio "+(a.track+1)+" · "+a.name);}for(EditorProject.EffectClip e:project.effects){items.add(e);labels.add("FX "+(e.track+1)+" · "+CreatorLooks.NAMES[e.preset]);}boolean[] checked=new boolean[items.size()];for(int i=0;i<items.size();i++)checked[i]=multiSelection.contains(items.get(i));new AlertDialog.Builder(this).setTitle("Select timeline items").setMultiChoiceItems(labels.toArray(new String[0]),checked,(d,i,on)->{if(on)multiSelection.items.add(items.get(i));else multiSelection.items.remove(items.get(i));refreshTimeline();}).setPositiveButton("Actions",(d,w)->selectionActions()).setNegativeButton("Done",(d,w)->refreshTimeline()).show();}
    private void selectionActions(){refreshTimeline();if(multiSelection.size()==0){notifyUser("This track has no items");return;}new AlertDialog.Builder(this).setTitle(multiSelection.size()+" items selected").setItems(new String[]{"Keep selection","Delete selected items","Select all tracks","Create compound from all tracks","Clear selection"},(d,w)->{if(w==1)new AlertDialog.Builder(this).setTitle("Delete selected items?").setMessage("Only the highlighted items will be removed. You can undo this edit.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(x,y)->change(()->multiSelection.delete(project))).show();else if(w==2){multiSelection.all(project);selectionActions();}else if(w==3)createCompoundPrompt();else if(w==4){multiSelection.clear();refreshTimeline();}}).show();}
    private void audioFormatDialog(){new AlertDialog.Builder(this).setTitle("Audio export format").setSingleChoiceItems(new String[]{"WAV · 16-bit PCM · enhancement / editing","MP3 · 192 kbps · smaller files","M4A · AAC · compact"},Arrays.asList("wav","mp3","m4a").indexOf(audioExportFormat),(d,w)->audioExportFormat=new String[]{"wav","mp3","m4a"}[w]).setPositiveButton("Export",(d,w)->startAudioExport()).setNegativeButton("Cancel",null).show();}
    private void startAudioExport(){if(exporting)return;project.migrateAudio();audioRenderProject=null;detachedSource=null;audioOnlyExport=true;compoundExport=false;startExport();}
    private void detachAudio(){if(exporting||selectedTrack.equals("Audio")||objectTrack()||selectedOverlay>=0||selected<0||selected>=project.clips.size()){notifyUser("Select a main video clip to detach its sound");return;}if(project.audios.size()>=EditorProject.MAX_CLIPS){notifyUser("Project audio limit reached");return;}EditorProject.Clip source=project.clips.get(selected);try{MediaMetadataRetriever check=new MediaMetadataRetriever();try{check.setDataSource(this,Uri.parse(source.uri));if(!"yes".equals(check.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_AUDIO))){notifyUser("This video has no audio track");return;}}finally{check.release();}audioRenderProject=new EditorProject();EditorProject.Clip clip=source.copy();clip.timelineAt=0;audioRenderProject.clips.add(clip);detachedSource=source;detachedAt=project.offset(selected);audioOnlyExport=true;compoundExport=false;startExport();}catch(Exception e){audioRenderProject=null;detachedSource=null;notifyUser("Could not detach audio: "+e.getMessage());}}
    private void finishDetachedAudio(File rendered){final EditorProject.Clip source=detachedSource;final long at=detachedAt;io.execute(()->{File directory=new File(getFilesDir(),"editor-audio");File output=new File(directory,UUID.randomUUID()+".m4a");try{if(!directory.exists()&&!directory.mkdirs())throw new IOException("Audio storage unavailable");java.nio.file.Files.move(rendered.toPath(),output.toPath());MediaMetadataRetriever check=new MediaMetadataRetriever();long duration;try{check.setDataSource(output.getAbsolutePath());duration=Long.parseLong(check.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));if(!"yes".equals(check.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_AUDIO)))throw new IOException("No readable detached sound");}finally{check.release();}EditorProject.Audio sound=new EditorProject.Audio();sound.uri=output.getAbsolutePath();sound.name="Audio · "+source.name;sound.duration=sound.end=duration;sound.at=at;main.post(()->{if(exportCancelled||isFinishing()||isDestroyed()||!project.clips.contains(source)){output.delete();return;}exporting=false;audioOnlyExport=false;audioRenderProject=null;detachedSource=null;if(exportDialog!=null)exportDialog.dismiss();checkpoint();source.volume=0;sound.track=project.audioTracks();project.audios.add(sound);selectedAudio=project.audios.size()-1;selectedOverlay=selectedCaption=-1;selectedTrack="Audio";tool="Music";position=at;committed();showEditor();notifyUser("Sound detached · video muted · select audio and tap Split");});}catch(Exception e){output.delete();main.post(()->exportFailed("Audio detach failed: "+e.getMessage()));}});}
    private void createCompoundPrompt(){if(exporting)return;new AlertDialog.Builder(this).setTitle("Create compound clip?").setMessage("Render all tracks into one video clip with their mixed audio, effects and timing. The original layers are kept so you can unpack the compound later. Keep the app open while rendering.").setNegativeButton("Cancel",null).setPositiveButton("Create compound",(d,w)->createCompound()).show();}
    private void createCompound(){try{project.migrateAudio();File dir=new File(getFilesDir(),"editor-compounds");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Cannot create compound storage");long needed=Math.max(150_000_000L,project.duration()*2500L);if(dir.getUsableSpace()<needed)throw new IOException("Not enough storage for the compound render");compoundOriginal=EditorProject.from(project.json().toString());File source=new File(dir,UUID.randomUUID()+".json");try(FileOutputStream out=new FileOutputStream(source)){out.write(compoundOriginal.json().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}compoundSourcePath=source.getAbsolutePath();audioRenderProject=null;detachedSource=null;audioOnlyExport=false;compoundExport=true;startExport();}catch(Exception e){compoundExport=false;notifyUser("Compound: "+e.getMessage());}}
    private static int[] displayDimensions(MediaMetadataRetriever metadata){int width=Integer.parseInt(metadata.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH)),height=Integer.parseInt(metadata.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));String value=metadata.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION);int rotation=value==null?0:Math.floorMod(Integer.parseInt(value),360);if(rotation==90||rotation==270){int swap=width;width=height;height=swap;}return new int[]{width,height};}
    private void repairCompoundGeometry(EditorProject target){boolean changed=false;ArrayList<EditorProject.Clip> candidates=new ArrayList<>(target.clips);for(EditorProject.Overlay layer:target.overlays)candidates.add(layer.clip);for(EditorProject.Clip clip:candidates){if(clip.compoundSource.isEmpty()||!checkedCompoundGeometry.add(clip.uri))continue;MediaMetadataRetriever metadata=new MediaMetadataRetriever();try{metadata.setDataSource(this,Uri.parse(clip.uri));int[] dimensions=displayDimensions(metadata);if(clip.width!=dimensions[0]||clip.height!=dimensions[1]){clip.width=dimensions[0];clip.height=dimensions[1];changed=true;}}catch(Exception e){checkedCompoundGeometry.remove(clip.uri);android.util.Log.w("SoloExport","Cannot inspect compound orientation",e);}finally{try{metadata.release();}catch(IOException ignored){}}}if(changed)try{target.save(this);}catch(Exception e){android.util.Log.w("SoloExport","Cannot persist compound orientation repair",e);}}
    private void finishCompound(File rendered){final EditorProject source=compoundOriginal;final String sourcePath=compoundSourcePath;io.execute(()->{File output=new File(new File(getFilesDir(),"editor-compounds"),UUID.randomUUID()+".mp4");try{java.nio.file.Files.move(rendered.toPath(),output.toPath());MediaMetadataRetriever check=new MediaMetadataRetriever();long duration;int width,height;try{check.setDataSource(output.getAbsolutePath());duration=Long.parseLong(check.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));int[] displayed=displayDimensions(check);width=displayed[0];height=displayed[1];if(duration<1)throw new IOException("Compound render is empty");}finally{check.release();}EditorProject.Clip group=new EditorProject.Clip(output.getAbsolutePath(),"Compound · "+source.name,duration);group.width=width;group.height=height;group.compoundSource=sourcePath;group.timelineAt=0;main.post(()->{if(exportCancelled||isFinishing()||isDestroyed()){output.delete();return;}exporting=false;compoundExport=false;if(exportDialog!=null)exportDialog.dismiss();checkpoint();project.clips.clear();project.overlays.clear();project.captions.clear();project.audios.clear();project.effects.clear();project.music="";project.clips.add(group);selected=0;selectedAudio=selectedOverlay=selectedCaption=selectedEffect=-1;selectedTrack="Video";position=0;committed();showEditor();notifyUser("Compound created · Select → Unpack restores source layers");});}catch(Exception e){output.delete();main.post(()->exportFailed("Compound failed: "+e.getMessage()));}});}
    private void unpackCompound(){if(selectedTrack.equals("Audio")||objectTrack()||selectedOverlay>=0||selected<0||selected>=project.clips.size()||project.clips.get(selected).compoundSource.isEmpty()){notifyUser("Select a compound clip on the main track");return;}EditorProject.Clip group=project.clips.get(selected);if(group.start!=0||group.end!=group.duration||group.speed!=1){notifyUser("Reset the compound trim and speed before unpacking its source layers");return;}try{EditorProject original=EditorProject.from(new String(java.nio.file.Files.readAllBytes(new File(group.compoundSource).toPath()),java.nio.charset.StandardCharsets.UTF_8));if(project.clips.size()-1+original.clips.size()>EditorProject.MAX_CLIPS||project.overlays.size()+original.overlays.size()>EditorProject.MAX_CLIPS||project.captions.size()+original.captions.size()>EditorProject.MAX_CLIPS||project.audios.size()+original.audios.size()>EditorProject.MAX_CLIPS)throw new IOException("Project item limit reached");checkpoint();long base=project.offset(selected);EditorEdits.freezeMain(project);EditorEdits.freezeMain(original);project.clips.remove(selected);for(EditorProject.Clip c:original.clips){c.timelineAt+=base;project.clips.add(c);}int videoRow=project.videoTracks(),audioRow=project.audioTracks(),fxRow=project.effectTracks(),textRow=project.textTracks(),imageRow=project.imageTracks(),stickerRow=project.stickerTracks();for(EditorProject.Overlay o:original.overlays){o.at+=base;o.track+=videoRow;project.overlays.add(o);}for(EditorProject.Audio a:original.audios){a.at+=base;a.track+=audioRow;project.audios.add(a);}for(EditorProject.Caption c:original.captions){c.at+=base;c.end+=base;c.track+=c.type.equals("Text")?textRow:c.type.equals("Image")?imageRow:stickerRow;project.captions.add(c);}for(EditorProject.EffectClip e:original.effects){e.at+=base;e.end+=base;e.track+=fxRow;project.effects.add(e);}project.clips.sort((a,b)->Long.compare(a.timelineAt,b.timelineAt));selected=0;position=base;committed();showEditor();notifyUser("Compound unpacked · original layers restored");}catch(Exception e){notifyUser("Could not unpack compound: "+e.getMessage());}}
    private void toggleMainGaps(){change(()->project.allowMainGaps=!project.allowMainGaps);notifyUser(project.allowMainGaps?"Main-track gaps allowed":"Main-track gaps closed automatically");}
    private String exportErrorDetail(Throwable error){Throwable cause=error;for(int i=0;i<8&&cause.getCause()!=null;i++)cause=cause.getCause();return cause.getMessage()==null?error.getMessage():cause.getMessage();}
    private void startExport(){
        long estimate=Math.max(150_000_000L,project.duration()*2500L);if(getCacheDir().getUsableSpace()<estimate){audioOnlyExport=false;compoundExport=false;audioRenderProject=null;detachedSource=null;notifyUser("Not enough free space for temporary and exported video");return;}
        main.removeCallbacks(previewUpdate);releasePlayer();exportCancelled=false;exporting=true;exportFile=new File(getCacheDir(),"edit-"+UUID.randomUUID()+(audioOnlyExport?".m4a":".mp4"));
        LinearLayout panel=column();exportProgress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);exportProgress.setMax(100);panel.addView(exportProgress);panel.addView(text("Keep Solo Camera open. You can cancel safely; your draft is saved.",13,MUTED));
        exportDialog=new AlertDialog.Builder(this).setTitle("Exporting 0%").setView(panel).setNegativeButton("Cancel",(d,w)->cancelExport("Export canceled; draft saved")).setCancelable(false).create();exportDialog.show();
        try{
            Composition composition=audioOnlyExport?EditorComposition.audio(audioRenderProject==null?project:audioRenderProject):EditorComposition.build(project);
            transformer=new Transformer.Builder(this).setMaxDelayBetweenMuxerSamplesMs(60000).setMuxerFactory(new InAppMp4Muxer.Factory()).setVideoMimeType(MimeTypes.VIDEO_H264).setAudioMimeType(MimeTypes.AUDIO_AAC).setEncoderFactory(new DefaultEncoderFactory.Builder(this).setRequestedVideoEncoderSettings(new VideoEncoderSettings.Builder().setBitrate(project.height==720?4_000_000:10_000_000).build()).build()).addListener(new Transformer.Listener(){
                @Override public void onCompleted(Composition c,ExportResult result){transformer=null;main.removeCallbacks(exportTick);if(exportCancelled)return;if(exportDialog!=null)exportDialog.setTitle("Saving export…");if(compoundExport)finishCompound(exportFile);else if(detachedSource!=null)finishDetachedAudio(exportFile);else publishExport(exportFile);}
                @Override public void onError(Composition c,ExportResult result,ExportException error){transformer=null;android.util.Log.e("SoloExport","Export error code="+error.errorCode,error);exportFailed("Export failed ("+error.errorCode+"): "+exportErrorDetail(error));}
            }).build();transformer.start(composition,exportFile.getAbsolutePath());main.post(exportTick);
        }catch(Exception e){exportFailed("Could not export: "+e.getMessage());}
    }
    private final Runnable exportTick=new Runnable(){public void run(){if(transformer!=null&&exporting){ProgressHolder holder=new ProgressHolder();int status=transformer.getProgress(holder);if(status==Transformer.PROGRESS_STATE_AVAILABLE){exportProgress.setIndeterminate(false);exportProgress.setProgress(holder.progress);exportDialog.setTitle("Exporting "+holder.progress+"%");}else exportProgress.setIndeterminate(true);main.postDelayed(this,400);}}};
    private void publishExport(File file){final boolean audioExport=audioOnlyExport;final String format=audioExport?audioExportFormat:"mp4";io.execute(()->{Uri output=null;File processed=file;try{
        if(audioExport&&!format.equals("m4a")){main.post(()->{if(exportDialog!=null)exportDialog.setTitle("Encoding "+format.toUpperCase(Locale.ROOT)+" audio…");});processed=EditorAudioFormats.convert(file,format,()->exportCancelled);}
        MediaMetadataRetriever check=new MediaMetadataRetriever();long duration;int width=0,height=0;try{check.setDataSource(processed.getAbsolutePath());if(!"yes".equals(check.extractMetadata(audioExport?MediaMetadataRetriever.METADATA_KEY_HAS_AUDIO:MediaMetadataRetriever.METADATA_KEY_HAS_VIDEO)))throw new IOException("Export has no readable "+(audioExport?"audio":"video"));duration=Long.parseLong(check.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));if(duration<=0)throw new IOException("Export is empty");if(!audioExport){int[] displayed=displayDimensions(check);width=displayed[0];height=displayed[1];}}finally{check.release();}
        if(exportCancelled)throw new IOException("Export canceled");String mime=!audioExport?"video/mp4":format.equals("wav")?"audio/wav":format.equals("mp3")?"audio/mpeg":"audio/mp4";String folder=audioExport?"Music/SoloCamera/Exports":"Movies/SoloCamera/Exports";ContentValues values=new ContentValues();values.put(MediaStore.MediaColumns.DISPLAY_NAME,"story-"+System.currentTimeMillis()+"."+format);values.put(MediaStore.MediaColumns.MIME_TYPE,mime);values.put(MediaStore.MediaColumns.RELATIVE_PATH,folder);values.put(MediaStore.MediaColumns.IS_PENDING,1);if(audioExport)values.put(MediaStore.Audio.Media.DURATION,duration);else{values.put(MediaStore.Video.Media.DURATION,duration);values.put(MediaStore.Video.Media.WIDTH,width);values.put(MediaStore.Video.Media.HEIGHT,height);values.put(MediaStore.Video.Media.DATE_TAKEN,System.currentTimeMillis());}output=getContentResolver().insert(audioExport?MediaStore.Audio.Media.EXTERNAL_CONTENT_URI:MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);if(output==null)throw new IOException("Could not create exported file");
        try(InputStream in=new FileInputStream(processed);OutputStream out=getContentResolver().openOutputStream(output,"w")){if(out==null)throw new IOException("Could not write exported file");byte[] buffer=new byte[128*1024];int count;while((count=in.read(buffer))!=-1){if(exportCancelled)throw new IOException("Export canceled");out.write(buffer,0,count);}}
        if(exportCancelled)throw new IOException("Export canceled");values.clear();values.put(MediaStore.MediaColumns.IS_PENDING,0);if(getContentResolver().update(output,values,null,null)!=1)throw new IOException("Could not publish exported file");try(Cursor c=getContentResolver().query(output,new String[]{MediaStore.MediaColumns.DATA},null,null,null)){if(c!=null&&c.moveToFirst()){String path=c.getString(0);if(path!=null)android.media.MediaScannerConnection.scanFile(this,new String[]{path},new String[]{mime},null);}}Uri saved=output;main.post(()->{exporting=false;audioOnlyExport=false;lastExport=saved;if(exportDialog!=null)exportDialog.dismiss();if(active&&!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setTitle("Export saved · "+format.toUpperCase(Locale.ROOT)).setMessage(folder+(audioExport?"\nShare this audio with your enhancement app.":"\nIf CapCut cannot list this video, give it access to all videos in Android app permissions, or use Open / share below.")).setPositiveButton("Play",(d,w)->playSource(saved,"Exported story")).setNeutralButton("Open / share",(d,w)->share(saved)).setNegativeButton("Done",(d,w)->rebuildPreview(false)).show();});
        }catch(Exception e){if(output!=null)try{getContentResolver().delete(output,null,null);}catch(Exception ignored){}main.post(()->exportFailed(e.getMessage()));}finally{if(!processed.equals(file))processed.delete();file.delete();}
    });}
    private void share(Uri uri){Intent intent=new Intent(Intent.ACTION_SEND);String mime=getContentResolver().getType(uri);intent.setType(mime==null?"video/mp4":mime);intent.putExtra(Intent.EXTRA_STREAM,uri);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(Intent.createChooser(intent,"Share your story"));}catch(ActivityNotFoundException e){notifyUser("No sharing app is available");}}
    private void exportFailed(String error){main.removeCallbacks(exportTick);exporting=false;audioOnlyExport=false;compoundExport=false;audioRenderProject=null;detachedSource=null;if(exportDialog!=null)exportDialog.dismiss();if(exportFile!=null&&exportFile.exists())exportFile.delete();if(!isFinishing()&&!isDestroyed()){notifyUser(error);if(active)rebuildPreview(false);}}
    private void cancelExport(String reason){exportCancelled=true;if(transformer!=null){transformer.cancel();transformer=null;}exportFailed(reason);}
    @Override protected void onResume(){super.onResume();active=true;if(player==null&&livePreview==null&&!exporting){if(editing&&!importingOverlay)rebuildPreview(false);else if(playbackUri!=null)startSourcePlayer();}main.removeCallbacks(tick);if(player!=null||livePreview!=null)main.post(tick);}
    @Override protected void onStop(){cancelPrivacyDrawing();cancelVoiceover();active=false;main.removeCallbacks(previewUpdate);releasePlayer();save();if(exporting)cancelExport("Export canceled because the editor was closed; draft saved");super.onStop();}
    @Override protected void onDestroy(){cancelPrivacyDrawing();generation++;cancelAiDownload=true;if(aiDownloadDialog!=null&&aiDownloadDialog.isShowing())aiDownloadDialog.dismiss();main.removeCallbacks(previewUpdate);main.removeCallbacks(exportTick);releasePlayer();io.shutdown();super.onDestroy();}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);if(project!=null)try{out.putString("project",project.json().toString());}catch(Exception ignored){}out.putInt("selected",selected);out.putInt("selectedAudio",selectedAudio);out.putInt("selectedCaption",selectedCaption);out.putInt("selectedOverlay",selectedOverlay);out.putString("selectedTrack",selectedTrack);out.putString("tool",tool);out.putBoolean("editing",editing);out.putLong("position",position);}
    @Override public void onBackPressed(){if(exporting)return;if(audioImportScreen||aiScreen){returnToEditor();return;}if(editing||playbackUri!=null)showLibrary();else super.onBackPressed();}
